function(container, apiUrl, tables) {
    // 売上実績データ管理画面の初期化

    // 売上データ一覧の読み込み
    function loadSalesData() {
        window.aivicApi.list('sales_data', {})
            .then(data => {
                const tbody = container.querySelector('#salesDataTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    data.forEach(item => {
                        const row = document.createElement('tr');
                        row.innerHTML = `
                            <td>${item.date || ''}</td>
                            <td>${item.product_name || ''}</td>
                            <td>${item.store_name || ''}</td>
                            <td>${item.sales_amount || 0}</td>
                            <td>${item.quantity || 0}</td>
                            <td>
                                <button class="btn-edit" data-id="${item.id}">編集</button>
                                <button class="btn-delete" data-id="${item.id}">削除</button>
                            </td>
                        `;
                        tbody.appendChild(row);
                    });

                    // 編集・削除ボタンのイベントハンドラー
                    tbody.querySelectorAll('.btn-edit').forEach(btn => {
                        btn.addEventListener('click', (e) => {
                            const id = e.target.dataset.id;
                            editSalesData(id);
                        });
                    });

                    tbody.querySelectorAll('.btn-delete').forEach(btn => {
                        btn.addEventListener('click', (e) => {
                            const id = e.target.dataset.id;
                            deleteSalesData(id);
                        });
                    });
                }
            })
            .catch(error => {
                window.aivicNotify.error('売上データの読み込みに失敗しました: ' + error.message);
            });
    }

    // 売上データの保存
    function saveSalesData() {
        const form = container.querySelector('#salesDataForm');
        if (!form) return;

        const formData = new FormData(form);
        const data = {
            date: formData.get('date'),
            product_name: formData.get('product_name'),
            store_name: formData.get('store_name'),
            sales_amount: parseFloat(formData.get('sales_amount')) || 0,
            quantity: parseInt(formData.get('quantity')) || 0
        };

        const id = formData.get('id');
        const apiCall = id ? 
            window.aivicApi.update('sales_data', id, data) :
            window.aivicApi.save('sales_data', data);

        apiCall
            .then(() => {
                window.aivicNotify.success('売上データを保存しました');
                form.reset();
                loadSalesData();
            })
            .catch(error => {
                window.aivicNotify.error('売上データの保存に失敗しました: ' + error.message);
            });
    }

    // 売上データの編集
    function editSalesData(id) {
        window.aivicApi.list('sales_data', { id: id })
            .then(data => {
                if (data.length > 0) {
                    const item = data[0];
                    const form = container.querySelector('#salesDataForm');
                    if (form) {
                        form.querySelector('[name="id"]').value = item.id;
                        form.querySelector('[name="date"]').value = item.date || '';
                        form.querySelector('[name="product_name"]').value = item.product_name || '';
                        form.querySelector('[name="store_name"]').value = item.store_name || '';
                        form.querySelector('[name="sales_amount"]').value = item.sales_amount || '';
                        form.querySelector('[name="quantity"]').value = item.quantity || '';
                    }
                }
            })
            .catch(error => {
                window.aivicNotify.error('売上データの取得に失敗しました: ' + error.message);
            });
    }

    // 売上データの削除
    function deleteSalesData(id) {
        if (confirm('この売上データを削除しますか？')) {
            window.aivicApi.delete('sales_data', id)
                .then(() => {
                    window.aivicNotify.success('売上データを削除しました');
                    loadSalesData();
                })
                .catch(error => {
                    window.aivicNotify.error('売上データの削除に失敗しました: ' + error.message);
                });
        }
    }

    // データ分析処理
    function analyzeSalesData() {
        const analysisType = container.querySelector('#analysisType')?.value;

        window.aivicApi.list('sales_data', {})
            .then(salesData => {
                let result;

                switch (analysisType) {
                    case 'product':
                        result = classifySalesDataByProduct(salesData);
                        break;
                    case 'store':
                        result = classifySalesDataByStore(salesData);
                        break;
                    case 'weather':
                        return Promise.all([
                            Promise.resolve(salesData),
                            collectWeatherData()
                        ]).then(([sales, weather]) => {
                            return analyzeCorrelationSalesWeather(sales, weather);
                        });
                    case 'event':
                        return Promise.all([
                            Promise.resolve(salesData),
                            collectEventData()
                        ]).then(([sales, events]) => {
                            return analyzeCorrelationSalesEvent(sales, events);
                        });
                    case 'seasonal':
                        return Promise.all([
                            Promise.resolve(salesData),
                            collectSeasonalData()
                        ]).then(([sales, seasonal]) => {
                            return analyzeCorrelationSalesSeason(sales, seasonal);
                        });
                    default:
                        result = collectSalesData(salesData);
                }

                return result;
            })
            .then(analysisResult => {
                const resultArea = container.querySelector('#analysisResult');
                if (resultArea) {
                    resultArea.innerHTML = `<pre>${JSON.stringify(analysisResult, null, 2)}</pre>`;
                }
                window.aivicNotify.success('データ分析が完了しました');
            })
            .catch(error => {
                window.aivicNotify.error('データ分析に失敗しました: ' + error.message);
            });
    }

    // イベントハンドラーの設定
    const saveBtn = container.querySelector('#saveSalesData');
    if (saveBtn) {
        saveBtn.addEventListener('click', saveSalesData);
    }

    const analyzeBtn = container.querySelector('#analyzeSalesData');
    if (analyzeBtn) {
        analyzeBtn.addEventListener('click', analyzeSalesData);
    }

    const refreshBtn = container.querySelector('#refreshSalesData');
    if (refreshBtn) {
        refreshBtn.addEventListener('click', loadSalesData);
    }

    // 初期データ読み込み
    loadSalesData();
}
